templates.code:
{
  "name": "Bandeja bajo control - borrador con IA",
  "nodes": [
    {
      "parameters": {
        "pollTimes": {
          "item": [
            {
              "mode": "everyMinute"
            }
          ]
        },
        "simple": false,
        "filters": {
          "labelIds": [
            "INBOX"
          ],
          "readStatus": "unread"
        },
        "options": {}
      },
      "id": "n8n-mail-01",
      "name": "Correo nuevo",
      "type": "n8n-nodes-base.gmailTrigger",
      "typeVersion": 1.2,
      "position": [
        -260,
        0
      ]
    },
    {
      "parameters": {
        "modelId": {
          "__rl": true,
          "value": "gpt-4o-mini",
          "mode": "list",
          "cachedResultName": "gpt-4o-mini"
        },
        "messages": {
          "values": [
            {
              "role": "system",
              "content": "Eres el asistente de [TU NOMBRE], que lleva [TU NEGOCIO]. Escribes borradores de respuesta en español de España, tuteando, en menos de 120 palabras. Nunca inventes precios, plazos ni disponibilidad: si el correo pide un dato que no tienes, deja el hueco escrito como [CONFIRMAR]. No prometas nada. Firma siempre como [TU NOMBRE]. Si el correo es publicidad, una factura automática o una notificación de una aplicacion, responde exactamente con la palabra IGNORAR y nada mas."
            },
            {
              "content": "=De: {{ $json.from.value[0].address }}\nAsunto: {{ $json.subject }}\n\n{{ $json.text }}"
            }
          ]
        },
        "options": {
          "temperature": 0.3
        }
      },
      "id": "n8n-mail-02",
      "name": "IA redacta",
      "type": "@n8n/n8n-nodes-langchain.openAi",
      "typeVersion": 1.8,
      "position": [
        -40,
        0
      ]
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": false,
            "leftValue": "",
            "typeValidation": "loose",
            "version": 2
          },
          "conditions": [
            {
              "id": "cond-ignorar",
              "leftValue": "={{ $json.message.content }}",
              "rightValue": "IGNORAR",
              "operator": {
                "type": "string",
                "operation": "notContains"
              }
            }
          ],
          "combinator": "and"
        },
        "looseTypeValidation": true,
        "options": {}
      },
      "id": "n8n-mail-03",
      "name": "Merece respuesta",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        180,
        0
      ]
    },
    {
      "parameters": {
        "resource": "draft",
        "subject": "=Re: {{ $('Correo nuevo').item.json.subject }}",
        "emailType": "text",
        "message": "={{ $json.message.content }}",
        "options": {
          "sendTo": "={{ $('Correo nuevo').item.json.from.value[0].address }}",
          "threadId": "={{ $('Correo nuevo').item.json.threadId }}"
        }
      },
      "id": "n8n-mail-04",
      "name": "Guardar borrador",
      "type": "n8n-nodes-base.gmail",
      "typeVersion": 2.1,
      "position": [
        420,
        -100
      ]
    }
  ],
  "connections": {
    "Correo nuevo": {
      "main": [
        [
          {
            "node": "IA redacta",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "IA redacta": {
      "main": [
        [
          {
            "node": "Merece respuesta",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Merece respuesta": {
      "main": [
        [
          {
            "node": "Guardar borrador",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "Asistente de WhatsApp",
  "nodes": [
    {
      "parameters": {
        "updates": [
          "messages"
        ]
      },
      "id": "n8n-wa-01",
      "name": "Mensaje de WhatsApp",
      "type": "n8n-nodes-base.whatsAppTrigger",
      "typeVersion": 1,
      "position": [
        -260,
        0
      ],
      "webhookId": "cambiame-al-importar"
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": true,
            "leftValue": "",
            "typeValidation": "loose",
            "version": 2
          },
          "conditions": [
            {
              "id": "cond-texto",
              "leftValue": "={{ $json.messages[0].type }}",
              "rightValue": "text",
              "operator": {
                "type": "string",
                "operation": "equals"
              }
            }
          ],
          "combinator": "and"
        },
        "looseTypeValidation": true,
        "options": {}
      },
      "id": "n8n-wa-02",
      "name": "Solo texto",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        -40,
        0
      ]
    },
    {
      "parameters": {
        "modelId": {
          "__rl": true,
          "value": "gpt-4o-mini",
          "mode": "list",
          "cachedResultName": "gpt-4o-mini"
        },
        "messages": {
          "values": [
            {
              "role": "system",
              "content": "Eres el asistente de WhatsApp de [TU NEGOCIO]. Contestas en español de España, tuteando, en 2 o 3 frases como maximo, sin listas ni negritas: es WhatsApp, no un correo. Datos que puedes dar: horario [TU HORARIO], direccion [TU DIRECCION], precios orientativos [TUS PRECIOS]. Si te preguntan algo que no esta en esa lista, contesta que lo mira una persona y que responden en menos de [TU PLAZO]. Nunca confirmes una reserva ni cobres nada."
            },
            {
              "content": "={{ $json.messages[0].text.body }}"
            }
          ]
        },
        "options": {
          "temperature": 0.4
        }
      },
      "id": "n8n-wa-03",
      "name": "IA contesta",
      "type": "@n8n/n8n-nodes-langchain.openAi",
      "typeVersion": 1.8,
      "position": [
        180,
        -100
      ]
    },
    {
      "parameters": {
        "operation": "send",
        "phoneNumberId": "PEGA_AQUI_TU_PHONE_NUMBER_ID",
        "recipientPhoneNumber": "={{ $('Mensaje de WhatsApp').item.json.messages[0].from }}",
        "textBody": "={{ $json.message.content }}",
        "additionalFields": {}
      },
      "id": "n8n-wa-04",
      "name": "Responder por WhatsApp",
      "type": "n8n-nodes-base.whatsApp",
      "typeVersion": 1,
      "position": [
        400,
        -100
      ]
    }
  ],
  "connections": {
    "Mensaje de WhatsApp": {
      "main": [
        [
          {
            "node": "Solo texto",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Solo texto": {
      "main": [
        [
          {
            "node": "IA contesta",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    },
    "IA contesta": {
      "main": [
        [
          {
            "node": "Responder por WhatsApp",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "Vigilante de mi web",
  "nodes": [
    {
      "parameters": {
        "rule": {
          "interval": [
            {
              "field": "minutes",
              "minutesInterval": 15
            }
          ]
        }
      },
      "id": "n8n-vig-01",
      "name": "Cada 15 minutos",
      "type": "n8n-nodes-base.scheduleTrigger",
      "typeVersion": 1.2,
      "position": [
        -280,
        0
      ]
    },
    {
      "parameters": {
        "url": "https://[TU-DOMINIO].com",
        "options": {
          "timeout": 10000,
          "response": {
            "response": {
              "fullResponse": true,
              "neverError": true
            }
          }
        }
      },
      "id": "n8n-vig-02",
      "name": "Llamar a la web",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        -60,
        0
      ]
    },
    {
      "parameters": {
        "conditions": {
          "options": {
            "caseSensitive": true,
            "leftValue": "",
            "typeValidation": "loose",
            "version": 2
          },
          "conditions": [
            {
              "id": "cond-caida",
              "leftValue": "={{ $json.statusCode }}",
              "rightValue": 200,
              "operator": {
                "type": "number",
                "operation": "notEquals"
              }
            }
          ],
          "combinator": "and"
        },
        "looseTypeValidation": true,
        "options": {}
      },
      "id": "n8n-vig-03",
      "name": "Esta caida",
      "type": "n8n-nodes-base.if",
      "typeVersion": 2.2,
      "position": [
        160,
        0
      ]
    },
    {
      "parameters": {
        "chatId": "PEGA_AQUI_TU_CHAT_ID",
        "text": "=🔴 [TU-DOMINIO].com no responde bien.\nCodigo: {{ $json.statusCode }}\nHora: {{ $now.setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm') }}",
        "additionalFields": {}
      },
      "id": "n8n-vig-04",
      "name": "Avisarme por Telegram",
      "type": "n8n-nodes-base.telegram",
      "typeVersion": 1.2,
      "position": [
        400,
        -100
      ]
    }
  ],
  "connections": {
    "Cada 15 minutos": {
      "main": [
        [
          {
            "node": "Llamar a la web",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Llamar a la web": {
      "main": [
        [
          {
            "node": "Esta caida",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Esta caida": {
      "main": [
        [
          {
            "node": "Avisarme por Telegram",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}

{
  "name": "Avisame cuando algo falle",
  "nodes": [
    {
      "parameters": {},
      "id": "n8n-err-01",
      "name": "Cuando falla un flujo",
      "type": "n8n-nodes-base.errorTrigger",
      "typeVersion": 1,
      "position": [
        -200,
        0
      ]
    },
    {
      "parameters": {
        "chatId": "PEGA_AQUI_TU_CHAT_ID",
        "text": "=⚠️ Se ha roto un flujo de n8n\n\nFlujo: {{ $json.workflow.name }}\nNodo: {{ $json.execution.lastNodeExecuted }}\nError: {{ $json.execution.error.message }}\n\nVerlo: {{ $json.execution.url }}",
        "additionalFields": {}
      },
      "id": "n8n-err-02",
      "name": "Avisarme por Telegram",
      "type": "n8n-nodes-base.telegram",
      "typeVersion": 1.2,
      "position": [
        40,
        0
      ]
    }
  ],
  "connections": {
    "Cuando falla un flujo": {
      "main": [
        [
          {
            "node": "Avisarme por Telegram",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "pinData": {},
  "settings": {
    "executionOrder": "v1"
  }
}
